        "id": "quiz",
        "component": "quiz_set",
        "title": "Self-Check Quiz",
        "pass_score": 70,
        "accent": "#0284c7",
        "questions": [
          {
            "question": "What process turns liquid water into water vapor using heat from the sun?",
            "options": [
              "Condensation",
              "Evaporation",
              "Precipitation",
              "Collection"
            ],
            "correct": 1,
            "explanation": "Evaporation is the process where liquid water absorbs heat and transforms into gas/vapor."
          },
          {
            "question": "Which phase of the water cycle directly forms clouds?",
            "options": [
              "Precipitation",
              "Evaporation",
              "Condensation",
              "Transpiration"
            ],
            "correct": 2,
            "explanation": "Cooling water vapor condenses into tiny droplets that gather to form clouds."
          },
          {
            "question": "When water droplets in clouds become too heavy, what happens?",
            "options": [
              "They evaporate instantly",
              "They fall as precipitation",
              "They turn into solid ice caps",
              "They stay suspended forever"
            ],
            "correct": 1,
            "explanation": "Gravity causes the heavy droplets to fall back to Earth as rain, snow, or other forms of precipitation."
